import axios from "axios";

const BASE_URL = "https://www.kobis.or.kr/kobisopenapi/webservice/rest/boxoffice/searchDailyBoxOfficeList.json";
const API_KEY = "d8e32f85c0227cc1338f9f4ac7cedb94"; // 발급받은 키로 교체

export const getDailyBoxOffice = async (targetDate) => {
  const response = await axios.get(BASE_URL, {
    params: {
      key: API_KEY,
      targetDt: targetDate, // yyyymmdd
    },
  });
  return response.data.boxOfficeResult.dailyBoxOfficeList;
};
